<script setup lang="ts">
import {ref,computed} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import DateRangeQuery from '../../components/DateRangeQuery.vue'
import {request,format} from '../../api'
import {work,resources,canUse,requireWorkspace,goCase,dayLabel,clock,money,type Row} from '../../workspace'
const tab=ref('phases'),plans=ref<Row[]>([]),invoice=ref<Row|null>(null),busy=ref(false),error=ref(''),expanded=ref<number[]>([])
const canViewStages=computed(()=>work.data?.capabilities?.can_view_stages??canUse('UC02'))
const canViewInvoices=computed(()=>work.data?.capabilities?.can_view_invoices??true)
const fromDate=ref(''),toDate=ref(''),invoiceRows=ref<Row[]|null>(null),invoiceMore=ref(true)
let appliedDates={from_date:'',to_date:''}
const invoices=computed(()=>invoiceRows.value??resources.value.invoices??[])
async function queryInvoices(append=false,retain=false){busy.value=true;error.value='';try{const dates=append||retain?appliedDates:{from_date:fromDate.value,to_date:toDate.value};if(dates.from_date&&dates.to_date&&dates.from_date>dates.to_date)throw Error('开始日期不能晚于结束日期');const before=append?invoices.value[invoices.value.length-1]?.id:null;const query=Object.entries({...dates,...(before?{before}:{})}).map(([k,v])=>k+'='+encodeURIComponent(String(v))).join('&');const result=await request('/api/records?resource=invoices&'+query);const previous=append?invoices.value:[];const ids=new Set(previous.map(r=>r.id));invoiceRows.value=[...previous,...result.items.filter((r:Row)=>!ids.has(r.id))];appliedDates=dates;invoiceMore.value=result.next!==null;invoice.value=null}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function resetDates(){fromDate.value='';toDate.value='';await queryInvoices()}
onLoad((q:any)=>{if(q?.dataset==='invoices')tab.value='invoices'})
onShow(async()=>{const ws=await requireWorkspace('UC14');if(!ws)return;if(invoiceRows.value!==null)await queryInvoices(false,true);if(!canViewStages.value){tab.value='invoices';plans.value=[];return}if(!canViewInvoices.value)tab.value='phases';busy.value=true;error.value='';try{const id=ws.resources.patients?.[0]?.id;if(id)plans.value=(await request('/api/patient-journey?patient_id='+id)).plans}catch(e:any){error.value=e.message}finally{busy.value=false}})
function toggle(id:number){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
async function openInvoice(row:Row){error.value='';try{invoice.value=await request('/api/invoices/'+row.id)}catch(e:any){error.value=e.message}}
function openCopy(){if(invoice.value)uni.navigateTo({url:'/pages/invoice/index?id='+invoice.value.id})}
const phaseCount=computed(()=>plans.value.reduce((n,p)=>n+p.phases.length,0))
</script>
<template>
<WorkspaceShell title="治疗接续与结算" active="UC14" back>
 <view class="page-heading"><view><text class="page-title">让治疗，顺畅接续</text><text class="page-description">查看牙医已确认的阶段安排，以及实际治疗产生的有效费用。</text></view><AppIcon name="flag" :size="32"/></view>
 <view v-if="work.data?.scope.role_code==='representative'" class="journey-note"><AppIcon name="person" :size="18"/><text>当前获授权患者：{{work.data?.scope.authorized_patient_name||resources.patients?.[0]?.full_name}}。按本次有效授权查询；切换患者请在“我的账号”选择已授权范围。</text></view><view class="view-tabs"><button v-if="canViewStages" :class="{selected:tab==='phases'}" @click="tab='phases';invoice=null">治疗阶段 <text>{{phaseCount}}</text></button><button v-if="canViewInvoices" :class="{selected:tab==='invoices'}" @click="tab='invoices'">有效结算 <text>{{invoices.length}}</text></button></view>
 <view v-if="error" class="error">{{error}}</view><view v-if="busy" class="empty-state"><text>正在读取已确认的安排…</text></view>
 <template v-else-if="tab==='phases'">
  <view class="journey-note"><AppIcon name="info" :size="20"/><text>先决阶段完成、牙医确认可约后，才能预约下一阶段。跨店就诊也沿用同一份治疗计划。</text></view>
  <view v-for="plan in plans" :key="plan.id" class="plan-card surface"><view class="plan-header"><view><text class="section-title">阶段治疗计划</text><text class="caption">{{plan.plan_no}} · 已确认版本 {{plan.revision_no}}</text></view><text class="status-label">{{plan.phases.filter((p:Row)=>p.progress_outcome==='completed').length}} / {{plan.phases.length}} 已完成</text></view>
   <view class="phase-list"><view v-for="(phase,i) in plan.phases" :key="phase.id" class="journey-phase" :class="{complete:phase.progress_outcome==='completed',ready:phase.can_book}"><view class="phase-rail"><view class="phase-marker"><AppIcon v-if="phase.progress_outcome==='completed'" name="checkmarkempty" color="#ffffff" :size="17"/><text v-else>{{i+1}}</text></view></view><view class="phase-body"><view class="phase-heading"><view><text class="phase-title">{{phase.phase_title}}</text><text class="caption">{{phase.clinic_name}}</text></view><text class="status-label">{{format(phase.progress_outcome)}}</text></view>
    <view class="phase-conditions"><text v-if="phase.predecessors.length">先决阶段：{{phase.predecessors.map((p:Row)=>p.phase_title+'（'+format(p.progress_outcome)+'）').join('、')}}</text><text v-else>此阶段无前序阶段依赖</text><text v-if="phase.earliest_at||phase.latest_at">可约窗口：{{phase.earliest_at?dayLabel(phase.earliest_at):'不限起日'}} 至 {{phase.latest_at?dayLabel(phase.latest_at):'待后续确认'}}</text><text v-if="phase.pause_or_end_reason">办理依据：{{phase.pause_or_end_reason}}</text></view>
    <view v-if="phase.appointment" class="linked-arrangement"><AppIcon name="calendar" :size="18"/><text>{{dayLabel(phase.appointment.starts_at)}} {{clock(phase.appointment.starts_at)}}—{{clock(phase.appointment.ends_at)}}</text><button class="text-button" @click="goCase('UC03',{id:phase.appointment.id})">查看预约</button></view>
    <view v-if="expanded.includes(phase.id)" class="phase-items"><view v-for="item in phase.items" :key="item.standard_id"><text>{{item.treatment_name}}<text v-if="item.site_description"> · {{item.site_description}}</text></text><text>计划数量 {{Number(item.planned_quantity)}}</text></view><text v-if="phase.estimated_fee!==null" class="caption">阶段预计 ¥{{money(phase.estimated_fee)}}，以实际实施后的有效结算为准。</text></view>
    <view class="phase-actions"><button class="text-button" @click="toggle(phase.id)">{{expanded.includes(phase.id)?'收起项目':'查看计划项目'}} <AppIcon :name="expanded.includes(phase.id)?'up':'down'" :size="13"/></button><button v-if="phase.can_book" class="primary" @click="goCase('UC02',{phase:phase.id})">预约此阶段</button><text v-else-if="!phase.appointment&&phase.progress_outcome==='waiting'" class="caption">等待前序完成或牙医复评</text></view>
   </view></view></view>
  </view>
  <view v-if="!plans.length" class="empty-state surface"><view class="empty-icon"><AppIcon name="flag" :size="34"/></view><text class="empty-title">暂无已确认的阶段计划</text><text>需要分阶段治疗时，牙医会与你确认方案。确认后的项目、先决条件与承接门店将在这里呈现。</text><button class="primary" @click="goCase('UC02')">安排一次就诊</button></view>
 </template>
 <template v-else><view class="journey-note"><AppIcon name="wallet" :size="20"/><text>费用依据已签署的实际治疗。此处不提供在线支付，也不以结算生成表示已经收款。</text></view>
  <DateRangeQuery v-model:from="fromDate" v-model:to="toDate" :busy="busy" label="结算开具日期" @query="queryInvoices()" @clear="resetDates"/><view class="invoice-layout" style="margin-top:18px"><view class="invoice-list"><button v-for="row in invoices" :key="row.id" class="invoice-card surface" :class="{selected:invoice?.id===row.id}" @click="openInvoice(row)"><view class="invoice-glyph"><AppIcon name="wallet" :size="25"/></view><view><text class="item-title">{{row.clinic_name}}</text><text class="caption">{{row.invoice_no}} · 第{{row.revision_no}}版</text><text class="caption">{{dayLabel(row.issued_at)}}</text></view><text class="invoice-amount">¥{{money(row.total_amount)}}</text><AppIcon name="right" :size="16"/></button><button v-if="invoices.length>=200&&invoiceMore" :disabled="busy" @click="queryInvoices(true)">加载更多结算</button><text class="caption">已读取 {{invoices.length}} 条授权范围内的有效结算</text><view v-if="!invoices.length" class="empty-state surface"><AppIcon name="wallet" :size="34"/><text class="empty-title">暂无有效结算</text><text>实际治疗签署并生成结算后，在这里查询明细。</text></view></view>
  <view v-if="invoice" class="invoice-detail surface"><view class="plan-header"><view><text class="section-title">实际治疗费用明细</text><text class="caption">{{invoice.invoice_no}}</text></view><button class="icon-button" @click="invoice=null"><AppIcon name="closeempty"/></button></view><view class="invoice-lines"><view v-for="line in invoice.lines" :key="line.id" class="invoice-line"><view><text>{{line.treatment_name_snapshot}}</text><text class="caption">{{'按签署的实际治疗'}} · {{Number(line.quantity_snapshot)}} {{line.unit_name_snapshot}} × ¥{{money(line.unit_price_snapshot)}}</text></view><text>¥{{money(line.subtotal)}}</text></view><view class="invoice-total"><text>本版合计</text><text>¥{{money(invoice.current_revision.total_amount)}}</text></view><button class="text-button" @click="openCopy">查看结算单副本 <AppIcon name="right" :size="15"/></button><text class="caption">当前有效版本 {{invoice.current_revision.revision_no}}。如有疑问，请向门店提供结算编号核对；更正会保留原版本。</text></view></view></view>
 </template>
</WorkspaceShell>
</template>
<style scoped>
.journey-note{display:flex;gap:12px;align-items:flex-start;color:#758296;line-height:1.8;font-size:13px;margin:22px 0}.journey-note>uni-icons{flex-shrink:0}.plan-card{margin:20px 0}.plan-header{padding:22px 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e3e8ef;gap:12px}.plan-header .caption{margin-top:6px}.phase-list{padding:28px 26px 8px}.journey-phase{display:flex;gap:20px}.phase-rail{position:relative;display:flex;justify-content:center;width:34px;flex-shrink:0}.phase-rail:after{content:'';position:absolute;top:36px;bottom:0;width:1px;background:#e3e8ef}.journey-phase:last-child .phase-rail:after{display:none}.phase-marker{width:32px;height:32px;border:1px solid #e3e8ef;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#f2f5f8;color:#758296;font-size:13px;z-index:1}.ready .phase-marker{border-color:#3278cf;color:#3278cf;background:#edf5ff}.complete .phase-marker{background:#3278cf;border-color:#3278cf}.phase-body{min-width:0;flex:1;padding-bottom:30px}.phase-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.phase-title{display:block;font-size:17px;font-weight:600;margin:3px 0 6px}.phase-conditions{font-size:13px;line-height:1.9;color:#758296;margin:14px 0;display:flex;flex-direction:column;gap:4px}.phase-actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.phase-actions .primary{font-size:13px;padding:9px 14px;min-height:40px}.phase-items{padding:14px 16px;background:#f2f5f8;border-radius:8px;margin-bottom:15px;font-size:13px}.phase-items>view{display:flex;justify-content:space-between;gap:14px;padding:7px 0}.phase-items>.caption{margin-top:8px}.linked-arrangement{display:flex;gap:9px;align-items:center;font-size:13px;background:#edf5ff;border-radius:8px;padding:12px;margin-bottom:16px}.linked-arrangement>button{margin-left:auto}.invoice-layout{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:start}.invoice-card{width:100%;text-align:left;display:flex;align-items:center;gap:15px;padding:20px;margin-bottom:12px}.invoice-glyph{background:#edf5ff;width:45px;height:45px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0}.invoice-card>.invoice-amount{margin-left:auto;font-weight:600;color:#3278cf;white-space:nowrap}.invoice-card.selected{border-color:#3278cf}.item-title{font-weight:600;display:block;margin-bottom:5px}.invoice-lines{padding:0 24px 24px}.invoice-line{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid #e3e8ef;font-size:14px}.invoice-line .caption{margin-top:5px}.invoice-line>text{white-space:nowrap}.invoice-total{display:flex;align-items:center;justify-content:space-between;margin:22px 0}.invoice-total>text:last-child{font-size:27px;font-weight:600;color:#3278cf}@media(max-width:1000px){.invoice-layout{grid-template-columns:1fr}}@media(max-width:680px){.plan-header{padding:19px 17px}.plan-header .section-title{font-size:16px}.phase-list{padding:23px 16px 0}.journey-phase{gap:12px}.phase-title{font-size:15px}.phase-heading{flex-wrap:wrap;gap:6px}.phase-conditions{font-size:12px}.phase-items{padding:12px;font-size:12px}.phase-actions>.caption{font-size:11px}.linked-arrangement{flex-wrap:wrap;font-size:12px}.invoice-card{padding:17px 14px;gap:10px}.invoice-glyph{width:37px;height:40px}.invoice-card .caption{font-size:10px;overflow-wrap:anywhere}.invoice-card>.invoice-amount{font-size:15px}.invoice-lines{padding:0 18px 22px}.invoice-line{font-size:13px}.invoice-line .caption{font-size:11px}.journey-note{font-size:12px}}
</style>
